"""Seating charts: students sorted by last name and split into rows."""


# ---
def seating_rows(students, seats_per_row):
    """One line of text per row, e.g. 'Row 1: Dunmere, Piet | Halloway, Juno'."""
    if seats_per_row <= 0:
        raise ValueError(f"seats per row must be positive, got {seats_per_row}")
    ordered = sorted(
        students, key=lambda s: (s.last_name.lower(), s.first_name.lower())
    )
    if not ordered:
        raise ValueError("no students to seat")
    lines = []
    for start in range(0, len(ordered), seats_per_row):
        names = " | ".join(s.display_name for s in ordered[start:start + seats_per_row])
        lines.append(f"Row {start // seats_per_row + 1}: {names}")
    return lines
