cat > tests/test_seating.py <<'EOF'
import unittest

from rosterkit.models import Student
from rosterkit.seating import seating_rows


def make(last, first):
    return Student(f"{last}{first}", last, first, "A")


class SeatingTests(unittest.TestCase):
    def test_when_students_are_unsorted(self):
        students = [make("Halloway", "Juno"), make("Dunmere", "Piet")]
        self.assertEqual(
            seating_rows(students, 2), ["Row 1: Dunmere, Piet | Halloway, Juno"]
        )

    def test_when_last_row_is_partial(self):
        students = [make("A", "a"), make("B", "b"), make("C", "c")]
        self.assertEqual(
            seating_rows(students, 2), ["Row 1: A, a | B, b", "Row 2: C, c"]
        )

    def test_when_seat_count_is_zero(self):
        with self.assertRaises(ValueError):
            seating_rows([make("A", "a")], 0)

    def test_when_seat_count_is_negative(self):
        with self.assertRaises(ValueError):
            seating_rows([make("A", "a")], -1)

    def test_when_no_students_are_given(self):
        with self.assertRaises(ValueError):
            seating_rows([], 3)
